import 'dart:convert';

import 'package:flutter/services.dart';
import 'package:logging/logging.dart';
import 'package:wqhub/joseki/joseki.dart';

/// Loads the bundled joseki collection (assets/joseki/joseki.json, generated by
/// tool/gen_joseki.dart) once at startup. Mirrors [TaskDB]'s singleton shape.
class JosekiDb {
  static final Logger _log = Logger('JosekiDb');
  static JosekiDb? _instance;

  factory JosekiDb() => _instance!;
  JosekiDb._(this.categories);

  final List<JosekiCategory> categories;

  Iterable<Joseki> get allJosekis =>
      categories.expand((c) => c.allJosekis);

  /// The josekis whose id is in [ids], in the collection's own order.
  List<Joseki> josekisByIds(Iterable<String> ids) {
    final wanted = ids.toSet();
    return [
      for (final j in allJosekis)
        if (wanted.contains(j.id)) j,
    ];
  }

  static Future<void> init() async {
    assert(_instance == null);
    _log.info('loading joseki collection');
    final data = await rootBundle.loadString('assets/joseki/joseki.json');
    final json = jsonDecode(data) as Map<String, dynamic>;
    _instance = JosekiDb._([
      for (final c in json['categories'] as List)
        JosekiCategory.fromJson(c as Map<String, dynamic>)
    ]);
  }
}
